print(pcall(error, "simples"))
print(pcall(error, "sem nível", 0))
print(pcall(error))
print(type(select(2, pcall(error, {msg = "tabela"}))))
local ok, e = pcall(function() error({code = 42}) end)
print(ok, e.code)
local ok2, e2 = pcall(function() error("com posição") end)
print(ok2, e2)
local ok3, e3 = pcall(function() error("nível 2", 2) end)
print(ok3, e3)
print(select("#", pcall(function() return 1, 2, 3 end)), pcall(function() return 1, 2, 3 end))
print(xpcall(function() error("x") end, function(m) return "tratado: " .. m end))
print(xpcall(function(a, b) return a + b end, print, 3, 4))
local ok4 = pcall(function() local t = nil; return t.x end)
print(ok4)
local ok5 = pcall(function() return 1 + {} end)
print(ok5)
local ok6 = pcall(function() return #5 end)
print(ok6)
local ok7 = pcall(function() return {} < {} end)
print(ok7)
print(select(2, pcall(assert, false, "afirmação")), select(2, pcall(assert, nil)))
print(assert(1, "não"), assert("v", 2, 3))
-- error with non-string values
print(pcall(error, 42), pcall(error, nil))
-- nested pcall
print(pcall(pcall, error, "e"))
-- error in metamethod
local mt = setmetatable({}, {__index = function() error("no índice", 0) end})
print(pcall(function() return mt.x end))
-- tostring of error with __tostring
local E = setmetatable({}, {__tostring = function() return "ErroCustom" end})
local _, ee = pcall(error, E)
print(tostring(ee))
